//! PS parity for `Battle::ally_targets`: at a scripted doubles position the
//! engine's flag-on (move, target, tera) set equals the set PS's
//! Side.chooseMove accepts (sim/side.ts:659-672, sim/battle.ts:2399-2429
//! validTargetLoc). The PS side is generated by
//! `node tools/ps-target-choices/target-choices.js
//!  tests/fixtures/ally-target-choices.input.json > ...ps.json`.

use std::collections::BTreeSet;
use vgc_engine_core::{Battle, BattleConfig, Choice, Format, SideRef};
use vgc_engine_golden::load_golden_team;

fn fixture(name: &str) -> serde_json::Value {
    let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures").join(name);
    serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap()
}

/// Engine choice -> PS command (relative target: foe slot s = s+1, own slot
/// s = -(s+1)). Switches / passes are outside the comparison.
fn ps_cmd(side: SideRef, c: &Choice) -> Option<String> {
    let (move_slot, target, tera) = match *c {
        Choice::Move { move_slot, target, .. } => (move_slot, target, false),
        Choice::Terastallize { move_slot, target, .. } => (move_slot, target, true),
        _ => return None,
    };
    let loc = target.map(|t| if t.side == side { -(t.slot as i32 + 1) } else { t.slot as i32 + 1 });
    Some(format!(
        "move {}{}{}",
        move_slot + 1,
        loc.map(|l| format!(" {l}")).unwrap_or_default(),
        if tera { " terastallize" } else { "" }
    ))
}

#[test]
fn flag_on_choices_match_ps_valid_targets() {
    let input = fixture("ally-target-choices.input.json");
    let ps = fixture("ally-target-choices.ps.json");
    let team = |k: &str| load_golden_team(input[k]["team"].as_str().unwrap(), false).unwrap();
    let mut b = Battle::new(BattleConfig { format: Format::Doubles, seed: 1 }, team("p1"), team("p2"));
    b.ally_targets = true;
    let mut ally_seen = 0;
    for (side, key) in [(SideRef::P1, "p1"), (SideRef::P2, "p2")] {
        for slot in 0..2u8 {
            let engine: BTreeSet<String> =
                b.legal_choices(side, slot).iter().filter_map(|c| ps_cmd(side, c)).collect();
            let want: BTreeSet<String> = ps[key][slot as usize]
                .as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_str().unwrap().to_string())
                .collect();
            assert_eq!(engine, want, "{key} slot {slot}");
            ally_seen += engine.iter().filter(|c| c.contains(" -")).count();
        }
    }
    assert!(ally_seen > 0, "fixture exercises ally targets");
    // Flag off drops exactly the ally-targeted commands.
    b.ally_targets = false;
    let off: BTreeSet<String> = b.legal_choices(SideRef::P1, 0).iter().filter_map(|c| ps_cmd(SideRef::P1, c)).collect();
    let want: BTreeSet<String> = ps["p1"][0]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .filter(|c| !c.contains(" -"))
        .collect();
    assert_eq!(off, want);
}
